sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event}) {
    // Replace with the actual schedule sys_id or bind dynamically
    // You can get this from another data resource on the page
    var scheduleSysId = api.data.<YOUR_DATA_RESOURCE>.schedule; 

    // If you know a specific schedule to test with, hardcode it first:
    // var scheduleSysId = '530423ea3bea4790d14ef10f23e45a7f';

    if (!scheduleSysId) return;

    var ga = new GlideAjax('x_travel_buddy_app.TBA_ScheduleEventsAjax');
    ga.addParam('sysparm_name', 'getScheduleEvents');
    ga.addParam('sysparm_schedule_id', scheduleSysId);
    ga.getXMLAnswer(function(response) {
        try {
            var result = JSON.parse(response);
            api.setState('calendarEvents', result.events);
        } catch(e) {
            console.error('Failed to parse schedule events:', e);
        }
    });
}
